import { readFileSync } from 'node:fs';
import path from 'node:path';

import { expect, type Page } from '@playwright/test';

export interface Account { label: string; name: string; email: string; password: string }

/** Demo accounts are generated by the local seed (random passwords) and never committed. */
export function accounts(): Account[] {
  const file = path.resolve(import.meta.dirname, '..', '..', 'var', 'demo-credentials.txt');
  return readFileSync(file, 'utf8').split(/\r?\n/).slice(2).filter(Boolean).map((line) => {
    const parts = line.trim().split(/\s{2,}/);
    return { label: parts[0], name: parts[1], email: parts[2], password: parts[3] };
  });
}

export const account = (label: string, index = 0) => accounts().filter((a) => a.label.startsWith(label))[index];

export interface Scenario { key: string; mrn: string | null; patient_name: string | null; birth_date: string | null }

/** Named seed scenarios (written by the seed to var/seed-manifest.json). */
export function scenario(key: string): Scenario {
  const file = path.resolve(import.meta.dirname, '..', '..', 'var', 'seed-manifest.json');
  const all = JSON.parse(readFileSync(file, 'utf8')).scenarios as Scenario[];
  return all.find((s) => s.key === key)!;
}

export function watchConsole(page: Page): string[] {
  const errors: string[] = [];
  page.on('console', (msg) => { if (msg.type() === 'error') errors.push(msg.text()); });
  page.on('pageerror', (err) => errors.push(err.message));
  return errors;
}

export async function signIn(page: Page, who: Account) {
  await page.goto('/');
  await page.getByLabel('Email').fill(who.email);
  await page.getByLabel('Password').fill(who.password);
  await page.getByRole('button', { name: 'Sign in' }).click();
  await expect(page.getByRole('button', { name: who.name })).toBeVisible();
}
